    Type parameterType = ReflectJvmMapping.getJavaType(source);

    if (parameterType instanceof Class) {
        return target.isAssignableFrom((Class<?>) parameterType);
    } else if (parameterType instanceof ParameterizedType) {
        ParameterizedType paramType = (ParameterizedType) parameterType;
        Type rawType = paramType.getRawType();
        if (rawType instanceof Class) {
            return target.isAssignableFrom((Class<?>) rawType);
        }
    }

    return false;
}

